Script:
Import-Module PackageManagement -MinimumVersion 1.4

Write-Host "Welcome to deploy package step template!"

$packagesRoot = $Jaws.PackageFolder
$workFolder = $pwd
$packageId = $Jaws.Parameters["STEP.PackageDetails.Package.PackageId"].Value
$packageVersion = $Jaws.Packages[$packageId].PackageVersion
$packageType = $Jaws.Packages[$packageId].PackageType
$packageFileName = $Jaws.Packages[$packageId].FileName
$packageDestination = $workFolder

# note: "$packageId.$packageVersion" is default NuGet Install-Package convention
$packageContents = Join-Path $packageDestination "$packageId.$packageVersion"

if (-not (Test-Path $packageContents)) {
  New-Item $packageContents -ItemType Directory
}

Switch ($packageType) {
  "nupkg" {
    Write-Host "Unzipping package $packageId @ $packageVersion of type $packageType from $packagesRoot to $packageDestination using Install-Package cmdlet"
    $possibleNupkgToRemove = Join-Path $packageContents "$packageId.$packageVersion.nupkg"
    $existed = Test-Path $possibleNupkgToRemove
    Install-Package -Name $packageId -RequiredVersion $packageVersion -Source $packagesRoot -Destination $packageDestination
    Write-Host "Package $packageId @ $packageVersion installed to $packageDestination"
    if (-not $existed -and (test-path $possibleNupkgToRemove)) {
      Write-Host "Removing $possibleNupkgToRemove after nupkg installation with Install-Package"
      Remove-Item $possibleNupkgToRemove
    }
  }

  "zip" {
    $sourceZip = Join-Path $packagesRoot $packageFileName
    Write-Host "Unzipping package $packageId @ $packageVersion of type $packageType from $sourceZip to $packageContents using Expand-Archive cmdlet"
    Expand-Archive $sourceZip $packageContents
    Write-Host "Package $packageId @ $packageVersion unzipped to $packageContents"
  }

  "tar" {
    $sourceTar = Join-Path $packagesRoot $packageFileName
    Write-Host "Un-tar package $packageId @ $packageVersion of type $packageType from $sourceTar to $packageContents using tar.exe"
    tar xvf $sourceTar -C $packageContents
    Write-Host "Package $packageId @ $packageVersion un-tarred to $packageContents"
  }

  "tar.gz" {
    $sourceTar = Join-Path $packagesRoot $packageFileName
    Write-Host "Unzip and un-tar package $packageId @ $packageVersion of type $packageType from $sourceTar to $packageContents using tar.exe"
    tar xvfz $sourceTar -C $packageContents
    Write-Host "Package $packageId @ $packageVersion unzipped and un-tarred to $packageContents"
  }
}

Write-Host "Package files are ready for transformations at $packageContents"


#SCRIPTREFERENCE(STEP.CustomScripts.AfterPackageExtracted)


# config transform
$transforms = $Jaws.Parameters["STEP.Transformations.ConfigTransforms"].Value
if ([string]::IsNullOrWhiteSpace($transforms) -eq $false) {
  Write-Host "Executing config transformations"
  @($transforms -Split "`n").Trim() | ForEach-Object {
    $transform = $_
    if ([string]::IsNullOrWhiteSpace($transform) -eq $false) {
      Write-Host "Processing config transformation $transform"
      $idx = $transform.IndexOf(':')
      if ($idx -lt 0) {
        throw "Transformation $transform is invalid"
      }
      $type = $transform.Substring(0, $idx).Trim().ToLowerInvariant()
      $data = $transform.Substring($idx + 1).Split("=>")
      $fileIn = Join-Path $packageContents $data[0].Trim()
      $fileOut = Join-Path $packageContents $data[1].Trim()
      switch ($type) {
        "xml" {
          Convert-JawsXmlTransform -xml $fileOut -xdt $fileIn
        }
        "json" {
          Convert-JawsJsonTransform -json $fileOut -jsonTransform $fileIn
        }
        Default {
          throw "Transformation $type is not supported"
        }
      }
    }
  }
}
else {
  Write-Host "No config transformations defined"
}


#SCRIPTREFERENCE(STEP.CustomScripts.AfterConfigTransformed)


# variable replacement
$files = $Jaws.Parameters["STEP.Transformations.VariableReplacement"].Value
if ([string]::IsNullOrWhiteSpace($files) -eq $false) {
  Write-Host "Variable replacement - starting"
  @($files -Split "`n").Trim() | ForEach-Object {
    if ([string]::IsNullOrWhiteSpace($_) -eq $false) {
      Write-Host "Variable replacement - processing $_"
      $absoluteFilePath = Join-Path $packageContents $_
      Convert-JawsVariableReplace -sourcePath $absoluteFilePath -variables $Jaws.Parameters
      Write-Host "Variable replacement - done $_"
    }    
  }
}
else {
  Write-Host "No files for variable replacement defined"
}

# hierarchical variable replacement
$files = $Jaws.Parameters["STEP.Transformations.JsonHierarchyVariableLocateAndReplace"].Value
if ([string]::IsNullOrWhiteSpace($files) -eq $false) {
  Write-Host "JSON hierarchical variable replacement - starting"
  @($files -Split "`n").Trim() | ForEach-Object {
    if ([string]::IsNullOrWhiteSpace($_) -eq $false) {
      Write-Host "JSON hierarchical variable replacement - processing $_"
      $absoluteFilePath = Join-Path $packageContents $_
      Convert-JawsJsonHierarchicalVariableReplace -sourcePath $absoluteFilePath -variables $Jaws.Parameters
      Write-Host "JSON hierarchical variable replacement - done $_"
    }
  }
}
else {
  Write-Host "No files for variable replacement defined"
}


#SCRIPTREFERENCE(STEP.CustomScripts.AfterVariablesReplaced)


# deploy to final location
Write-Host "Deploying files to installation directory"

$installDir = $Jaws.Parameters["STEP.PackageDetails.InstallationDirectory"].Value

if (-not $installDir) {
  throw "This deployment step is missing value for 'STEP.PackageDetails.InstallationDirectory'"
}

if (-not (Test-Path $installDir)) {
  Write-Host "Install directory is missing - creating $installDir"
  New-Item $installDir -ItemType Directory
  Write-Host "Install directory created - ready to copy files"
} else {
  Write-Host "Install directory exists - checking purge setting"
  if ($Jaws.Parameters["STEP.PackageDetails.PurgeInstallationDirectory"].Value -eq $true) {
    Write-Host "Purge flag enabled - purging $installDir"
    Remove-JawsFolderContents -folder $installDir -ignoreErrors $false
    Write-Host "$installDir purged - ready to copy files"
  } else {
    Write-Host "Purge flag disabled - ready to copy files"
  }
}
$packageContentsWildcard = Join-Path $packageContents "*"
Write-Host "Copying files $packageContentsWildcard to $installDir"
Move-Item -Force -Path $packageContentsWildcard -Destination $installDir
Write-Host "All files copied"


#SCRIPTREFERENCE(STEP.CustomScripts.AfterPackageDeployed)
